        cursor = (endpoint - 1) % size
        while residual[cursor] == 0:
            gap += 1
            cursor = (cursor - 1) % size
        if gap >= 2:
            value *= residual[endpoint] // 2 + 1
    return value


def height_formula(size, mass):
    if size <= 2 or mass == 0:
        return 0
    if size == 3:
        return (mass - 1).bit_length()
    return mass - 1


